from pathlib import Path
import json,html
r=Path(__file__).resolve().parent.parent;report=json.loads((r/'assets/medals/quality-report.json').read_text())
css='''*{box-sizing:border-box}body{margin:0;background:#e9e5d9;color:#10343f;font:16px/1.5 Arial}main{max-width:1600px;margin:auto;padding:30px}header{text-align:center;max-width:1000px;margin:auto auto 30px}h1{font-size:34px;margin-bottom:8px}h2{font-size:18px;margin:0 0 12px}p{margin:8px 0}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.item{background:#fffdf7;border:1px solid #cfc6b1;border-radius:14px;overflow:hidden;padding:18px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:4px}.sample{display:grid;place-items:center;min-width:0;aspect-ratio:1;padding:8px}.light{background:#fffdf7}.dark{background:#0b2330;color:#fff}.sample img{width:100%;height:100%;object-fit:contain}.tag{font-weight:bold;color:#90632f}small{font-size:12px}.runner{margin-top:28px;padding:24px;background:#fffdf7;border-radius:14px}.runner .sample{height:300px;aspect-ratio:auto}.runner .sample{display:block;overflow:hidden;padding:0}.runner img{display:block;width:100%;height:300px;object-fit:contain}@media(max-width:800px){.grid{grid-template-columns:1fr}main{padding:16px}}'''
entries=[]
for m in report['medals']:
 src=html.escape(m['source'].replace('assets/','../',1));label=html.escape(m['name']);tag='Bildekontroll bestått' if m['printReady'] else 'Ikke trykkklar'
 entries.append(f'<article class="item"><h2>{label}</h2><div class="pair"><div class="sample light"><img src="{src}" alt="{label} på lys flate"></div><div class="sample dark"><img src="{src}" alt="{label} på mørk flate"></div></div><p>{m["width"]} × {m["height"]} px · {"Alfa" if m["transparent"] else "Ugjennomsiktig bakgrunn"}</p><small>300 DPI: {m["maxPrintMm300"][0]:.1f} × {m["maxPrintMm300"][1]:.1f} mm</small><p class="tag">{tag}</p></article>')
watermark=json.loads((r/'data/badges.json').read_text())['watermark']
runner_src=html.escape(watermark['src'].removeprefix('assets/medals/'))
runner=f'<section class="runner"><h2>Morothon-løperen – valgt motiv</h2><p>Den siste grove varianten er godkjent av brukeren. PNG-teksturen beholdes. Teknisk trykkontroll gjenstår.</p><div class="pair"><div class="sample light"><img src="{runner_src}" alt="Godkjent løpermotiv på lys flate"></div><div class="sample dark"><img src="{runner_src}" alt="Godkjent løpermotiv på mørk flate"></div></div></section>'
(r/'assets/medals/review.html').write_text('<!doctype html><html lang="no"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Morothon – original- og trykkontroll</title><style>'+css+'</style><main><header><h1>Morothons offisielle medaljer</h1><p>Høyeste tilgjengelige originaler · lys og mørk bakgrunn · ingen nye motiver</p><p>Dette er en kildegjennomgang. Merker med fotobakgrunn er fortsatt ufrilagte. Kontrollstatus følger kvalitetsrapporten.</p></header><div class="grid">'+''.join(entries)+'</div>'+runner+'</main></html>')
